if(HipsMgr.getFlagShow()) {
    core.debug("HiPS surveys are visible");
} else {
    HipsMgr.setFlagShow(true);
}

// Enable HiPS surveys (e.g., DSS images)
HipsMgr.setFlagShow(true);

// Disable HiPS surveys
HipsMgr.setFlagShow(false);

// Toggle HiPS visibility
var current = HipsMgr.getFlagShow();
HipsMgr.setFlagShow(!current);

// Manually reload HiPS sources
HipsMgr.loadSources();
core.debug("Loading HiPS surveys...");

var survey = HipsMgr.getSurveyByUrl("https://alasky.cds.unistra.fr/DSS/DSS2M");
if(survey) {
    core.debug("Survey found: " + survey.getShortName());
    survey.setVisible(true);
}

var state = HipsMgr.getState();
if(state == 0) core.debug("HiPS not loaded yet");
else if(state == 1) core.debug("HiPS loading...");
else if(state == 2) core.debug("HiPS loaded");

if(HipsMgr.isLoaded()) {
    core.debug("HiPS surveys are ready");
} else {
    core.debug("HiPS surveys still loading...");
}
